def word_wrap(text, width):
    words = text.split()
    lines, cur = [], ''
    for w in words:
        if not cur:
            cur = w
        elif len(cur) + 1 + len(w) <= width:
            cur += ' ' + w
        else:
            lines.append(cur)
            cur = w
    if cur:
        lines.append(cur)
    return lines

def count_initial(text, letter):
    letter = letter.lower()
    return sum(1 for w in text.split() if w and w[0].lower() == letter)

def rle_encode(s):
    if not s:
        return ''
    out = []
    cur, n = s[0], 1
    for ch in s[1:]:
        if ch == cur:
            n += 1
        else:
            out.append(f'{cur}{n}')
            cur, n = ch, 1
    out.append(f'{cur}{n}')
    return ''.join(out)

def json_path_get(obj, path):
    import re
    cur = obj
    for seg in path.split('.'):
        m = re.match(r'^([A-Za-z0-9_]*)(\[\d+\])*$', seg)
        if not m:
            return None
        key = seg.split('[')[0]
        idxs = re.findall(r'\[(\d+)\]', seg)
        if key:
            if not isinstance(cur, dict) or key not in cur:
                return None
            cur = cur[key]
        for ix in idxs:
