def merge_intervals(intervals):
    if not intervals:
        return []
    ivs = sorted(intervals)
    out = [list(ivs[0])]
    for s, e in ivs[1:]:
        if s <= out[-1][1]:
            out[-1][1] = max(out[-1][1], e)
        else:
            out.append([s, e])
    return out

def longest_unique_len(s):
    seen = {}
    start = best = 0
    for i, ch in enumerate(s):
        if ch in seen and seen[ch] >= start:
            start = seen[ch] + 1
        seen[ch] = i
        best = max(best, i - start + 1)
    return best

def turnstile(events):
    state = 'LOCKED'
    alarms = 0
    for e in events:
        if e == 'coin':
            state = 'UNLOCKED'
        elif e == 'push':
            if state == 'UNLOCKED':
                state = 'LOCKED'
            else:
                alarms += 1
    return [state, alarms]

def eval_rpn(tokens):
    st = []
    for t in tokens:
        if t in ('+', '-', '*', '/'):
            b, a = st.pop(), st.pop()
            if t == '+':
                st.append(a + b)
            elif t == '-':
                st.append(a - b)
            elif t == '*':
                st.append(a * b)
            else:
                q = abs(a) // abs(b)
                st.append(q if (a >= 0) == (b >= 0) else -q)
        else:
            st.append(int(t))
    return st[0]

def base36_add(a, b):
    digs = '0123456789abcdefghijklmnopqrstuvwxyz'
    val = {c: i for i, c in enumerate(digs)}
    i, j, carry, out = len(a) - 1, len(b) - 1, 0, []
    while i >= 0 or j >= 0 or carry:
        da = val[a[i]] if i >= 0 else 0
        db = val[b[j]] if j >= 0 else 0
        s = da + db + carry
        out.append(digs[s % 36])
        carry = s // 36
        i -= 1
        j -= 1
    return ''.join(reversed(out))

def sliding_max(nums, k):
    from collections import deque
    dq = deque()
    out = []
    for i, x in enumerate(nums):
        while dq and dq[0] <= i - k:
            dq.popleft()
        while dq and nums[dq[-1]] <= x:
            dq.pop()
        dq.append(i)
        if i >= k - 1:
            out.append(nums[dq[0]])
    return out
